  'site.calculators.vastu.or': ' లేదా ',
  'site.calculators.vastu.title': 'వాస్తు కాలిక్యులేటర్',
  'site.calculators.vastu.intro': 'మీ ఇంటిలోని ప్రతి భాగం ఏ దిశలో ఉందో ఎంచుకోండి, సంప్రదాయ వాస్తు దిశా సూత్రాల ప్రకారం ఆ స్థానాలకు ఎంత స్కోరు వస్తుందో చూడండి.',
